package jCPU.x86;

import java.io.BufferedReader;
import java.io.FileInputStream;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Runs the snippets in golden/x86_64.golden through the x86-64 executor and
 * compares registers, flags and memory with what the real CPU produced.
 * The file is generated by golden/gen_golden.py; see golden/README.md.
 */
public class X86Amd64GoldenTest {
    private static final String GOLDEN = "golden/x86_64.golden";

    /* Memory layout; must match golden/runner.c. */
    private static final int CODE_ADDR = 0x100000;
    private static final int DATA_ADDR = 0x200000;
    private static final int STACK_ADDR = 0x300000;
    private static final int REGION_SIZE = 0x10000;
    /* The snippet ends with a jump to this address. */
    private static final long EXIT_ADDR = 0x1F0000;

    /* CF PF AF ZF SF DF OF */
    private static final long FLAG_MASK = 0xCD5;
    private static final int MAX_STEPS = 5_000_000;
    private static final int MAX_REPORTED = 20;

    private static final String[] REGS = {
        "rax", "rcx", "rdx", "rbx", "rsp", "rbp", "rsi", "rdi",
        "r8", "r9", "r10", "r11", "r12", "r13", "r14", "r15"
    };
    private static final long[] DEFAULT = {
        0x1122334455667788L, 0xC3, 0xFEDCBA9876543210L, 0x8000000000000001L,
        0x308000, 0x200300, 0x200200, 0x200100,
        0xFFFFFFFFFFFFFFFFL, 0x7FFFFFFFFFFFFFFFL, 0x80000000L, 0xFFFFFFFFL,
        0x200400, 0x200500, 3, 5
    };

    private static final byte[] PATTERN = new byte[REGION_SIZE];
    static {
        for (int i = 0; i < REGION_SIZE; i++) {
            PATTERN[i] = (byte) ((i * 31 + 7) ^ (i >> 8));
        }
    }

    private static InputStream openGolden() throws Exception {
        InputStream in = X86Amd64GoldenTest.class.getResourceAsStream(GOLDEN);
        return in != null ? in : new FileInputStream("test/jCPU/x86/" + GOLDEN);
    }

    private static byte[] hex(String s) {
        byte[] b = new byte[s.length() / 2];
        for (int i = 0; i < b.length; i++) {
            b[i] = (byte) Integer.parseInt(s.substring(2 * i, 2 * i + 2), 16);
        }
        return b;
    }

    /* Apply "rax=1,r8=2" to a copy of the given register values. */
    private static long[] withRegs(long[] base, String list) {
        long[] regs = base.clone();
        if (!list.isEmpty()) {
            for (String item : list.split(",")) {
                String[] kv = item.split("=");
                regs[Arrays.asList(REGS).indexOf(kv[0])] = Long.parseUnsignedLong(kv[1], 16);
            }
        }
        return regs;
    }

    /* Run one line of the golden file; returns null if the result matches. */
    private static String runCase(X86Core core, String line) {
        String[] f = line.split("\\|", -1);
        byte[] code = hex(f[1]);
        long[] init = withRegs(DEFAULT, f[2]);
        long flags = Long.parseLong(f[3], 16);
        long undefined = Long.parseLong(f[4], 16);
        long[] expected = withRegs(init, f[5]);
        long expectedFlags = Long.parseLong(f[6], 16);

        byte[] mem = core.getMemory();
        core.reset();
        core.setLongMode(true);
        core.setActiveExecutor(new X86Amd64());
        Arrays.fill(mem, CODE_ADDR, CODE_ADDR + REGION_SIZE, (byte) 0xCC);
        System.arraycopy(code, 0, mem, CODE_ADDR, code.length);
        // jmp [rip+0], followed by the address to jump to
        int tail = CODE_ADDR + code.length;
        mem[tail] = (byte) 0xFF;
        mem[tail + 1] = 0x25;
        Arrays.fill(mem, tail + 2, tail + 6, (byte) 0);
        core.writeMem64((long) tail + 6, EXIT_ADDR);
        System.arraycopy(PATTERN, 0, mem, DATA_ADDR, REGION_SIZE);
        Arrays.fill(mem, STACK_ADDR, STACK_ADDR + REGION_SIZE, (byte) 0);

        for (int i = 0; i < 16; i++) {
            core.setReg64(X86Core.REG_RAX + i, init[i]);
        }
        // Bit 1 is always set and interrupts are enabled, as on the real CPU.
        core.setRflags64((flags & FLAG_MASK) | 0x202);
        core.setPC64(CODE_ADDR);

        try {
            int steps = 0;
            while (core.getPC64() != EXIT_ADDR) {
                if (++steps > MAX_STEPS) {
                    return "did not finish within " + MAX_STEPS + " steps, RIP=0x"
                            + Long.toHexString(core.getPC64());
                }
                core.step();
            }
        } catch (Exception | Error ex) {
            return ex.toString().split("\n")[0];
        }

        StringBuilder diff = new StringBuilder();
        for (int i = 0; i < 16; i++) {
            long actual = core.getReg64(X86Core.REG_RAX + i);
            if (actual != expected[i]) {
                diff.append(String.format(" %s=%x (expected %x)", REGS[i], actual, expected[i]));
            }
        }
        long actualFlags = core.getRflags64() & FLAG_MASK;
        if (((actualFlags ^ expectedFlags) & ~undefined) != 0) {
            diff.append(String.format(" flags=%x (expected %x, undefined %x)",
                    actualFlags, expectedFlags, undefined));
        }

        byte[] data = PATTERN.clone();
        byte[] stack = new byte[REGION_SIZE];
        if (!f[7].equals("-")) {
            for (String item : f[7].split(",")) {
                String[] kv = item.split("=");
                int addr = Integer.parseInt(kv[0], 16);
                byte value = (byte) Integer.parseInt(kv[1], 16);
                if (addr >= STACK_ADDR) {
                    stack[addr - STACK_ADDR] = value;
                } else {
                    data[addr - DATA_ADDR] = value;
                }
            }
        }
        compareRegion(diff, mem, DATA_ADDR, data);
        compareRegion(diff, mem, STACK_ADDR, stack);
        return diff.length() == 0 ? null : diff.toString().trim();
    }

    private static void compareRegion(StringBuilder diff, byte[] mem, int base, byte[] expected) {
        int at = Arrays.mismatch(Arrays.copyOfRange(mem, base, base + REGION_SIZE), expected);
        if (at >= 0) {
            diff.append(String.format(" mem[%x]=%02x (expected %02x)",
                    base + at, mem[base + at] & 0xFF, expected[at] & 0xFF));
        }
    }

    @Test
    public void testAgainstRealCpu() throws Exception {
        X86Core core = new X86Core(64 * 1024 * 1024);
        List<String> failures = new ArrayList<>();
        int total = 0;
        try (BufferedReader in = new BufferedReader(
                new InputStreamReader(openGolden(), StandardCharsets.US_ASCII))) {
            String line;
            while ((line = in.readLine()) != null) {
                if (line.isEmpty() || line.startsWith("#")) {
                    continue;
                }
                total++;
                String problem = runCase(core, line);
                if (problem != null) {
                    failures.add(line.substring(0, line.indexOf('|')) + ": " + problem);
                }
            }
        }
        assertTrue("the golden file has no cases", total > 0);
        if (!failures.isEmpty()) {
            StringBuilder sb = new StringBuilder();
            sb.append(failures.size()).append(" of ").append(total).append(" cases differ from the real CPU:");
            for (String failure : failures.subList(0, Math.min(MAX_REPORTED, failures.size()))) {
                sb.append("\n  ").append(failure);
            }
            fail(sb.toString());
        }
    }
}
